// 4.4 Penjelasan bahasa awam untuk aturan SBO_SP_TransactionNotification / SBO_SP_PostTransactionNotice.
// Object, berlaku saat, pesan, status, kondisi & kode selalu diambil dari SP di DB oleh sp-parse.js. File ini hanya menambahkan
// nama, syarat (bahasa awam), kondisi yang sudah dirapikan, dan catatan temuan, untuk aturan yang sudah pernah dibaca manusia.
// Disusun dari SP KOM (DATA/SBO_SP_*KOM.sql, 2026-10-20).
//
//   object.type / types = object_type di SP. module = kelompok di halaman.
//   rule.k       = "val" (penjagaan, ada pesan) atau "proc" (proses otomatis).
//   rule.anchor  = teks yang ada di potongan kode aturan hasil sp-parse.js (biasanya pesan error). Cocok = penjelasan ini dipakai.
//                  Kalau SP di DB berubah dan anchor tidak ketemu, aturan tetap tampil dari kode, hanya tanpa penjelasan ini.
//   notes        = temuan yang tidak bisa dibaca otomatis; tampil kalau ada aturan object itu yang cocok.
// Teks bebas: syarat, kondisi (HTML), does (proses otomatis). msg & when di sini hanya catatan, yang tampil selalu dari DB.

const A = ["Add"], AU = ["Add", "Update"], U = ["Update"];
const CUBE = "Update/insert <code>STEM_LASTIMPORT_CUBE</code> untuk Plan tersebut: kalau Plan sudah ada di tabel, <code>UPDATETIME</code> diisi waktu update dokumen; "
  + "kalau belum, insert baris baru dengan <code>LASTIMPORT</code> = null. Plan dihitung ulang di import cube berikutnya.";
const BACKDATE = "[ERROR SP] : Transaksi tidak dapat diinput karena melebihi batas waktu {N} hari";
const FP_MSG = "[ERROR SP] : NO. FAKTUR PAJAK {8 digit terakhir} ALREADY EXISTS IN {jenis dokumen} DOCUMENT NO {DocNum}.";

const backdate = (no, param, tbl, dateCol = "DocDate", cancel = true) => ({ k: "val", no, name: "Batas backdate", when: A, param: [param], anchor: `'${param}'`,
  syarat: `Tanggal dokumen lebih lama dari N hari ke belakang dari hari ini.${cancel ? " Dokumen cancellation tidak kena." : ""}`,
  kondisi: `<code>${tbl}.${dateCol} &lt; hari ini − N hari</code>${cancel ? ` dan <code>${tbl}.CANCELED ≠ 'C'</code>` : ""} (N = isi param <code>${param}</code>)`, msg: BACKDATE });
const drItem = (no, h, l) => ({ k: "val", no, name: "Distribution Rule tipe Item", when: AU, anchor: "Distribution Rule Must be the same with COGS",
  syarat: "Dokumen tipe Item, lalu ada baris yang Distribution Rule-nya kosong atau berbeda dengan COGS Distribution Rule.",
  kondisi: `<code>${h}.DocType = 'I'</code> dan (<code>${l}.OcrCode</code> kosong atau <code>CogsOcrCod ≠ OcrCode</code> atau <code>CogsOcrCo2 ≠ OcrCode2</code> atau <code>CogsOcrCo3 ≠ OcrCode3</code>)`,
  msg: "[ERROR SP] : Distribution Rule Must be Filled or Distribution Rule Must be the same with COGS Distribution Rule" });
const drService = (no, h, l) => ({ k: "val", no, name: "Distribution Rule tipe Service", when: AU, anchor: "'[ERROR SP] : Distribution Rule Must be Filled'",
  syarat: "Dokumen tipe Service, lalu ada baris yang Distribution Rule-nya kosong.",
  kondisi: `<code>${h}.DocType = 'S'</code> dan <code>${l}.OcrCode</code> kosong`, msg: "[ERROR SP] : Distribution Rule Must be Filled" });
// Series: huruf terakhir nama Series dokumen ini harus sama dengan dokumen asal (base) / dokumen yang di-cancel
const series = (no, base, msgBase, anchor) => ({ k: "val", no, name: `Series sama dengan ${base}`, when: AU, anchor,
  syarat: `Series dokumen ini tidak sama dengan Series ${base} yang menjadi dasarnya.`,
  kondisi: `Huruf terakhir <code>NNM1.SeriesName</code> dokumen ini ≠ huruf terakhir Series ${base} (base lewat <code>BaseEntry/BaseLine</code>)`,
  msg: `[ERROR SP] : Kode Series tidak sesuai dengan kode Series ${msgBase}!` });
const seriesCancel = (no, doc) => ({ k: "val", no, name: "Series Cancellation", when: AU, anchor: "Kode Series tidak sesuai dengan Base Document",
  syarat: `Dokumen cancellation memakai Series yang berbeda dengan ${doc} yang di-cancel.`,
  kondisi: "<code>CANCELED = 'C'</code> dan huruf terakhir <code>SeriesName</code> ≠ huruf terakhir Series dokumen asal",
  msg: "[ERROR SP] : Kode Series tidak sesuai dengan Base Document!" });
const fp = (anchor, h, col) => ({ k: "val", no: "FP", name: "No. Faktur Pajak tidak boleh dobel", when: AU, anchor,
  syarat: "Nomor Faktur Pajak (8 digit terakhir) sudah dipakai dokumen lain yang tidak di-cancel: AR Invoice, AR Credit Memo, AP Credit Memo, atau AR DP Invoice. Nomor kosong atau '-' tidak dicek.",
  kondisi: `<code>RIGHT(${h}.${col}, 8)</code> sama dengan nomor FP di OINV / ORIN (<code>U_ST_NoFPI</code>) / ORPC / ODPI yang <code>CANCELED = 'N'</code>`, msg: FP_MSG });
const fpNext = { k: "proc", no: "FP", name: "Update nomor Faktur Pajak berikutnya", when: A, anchor: "CALL STEM_UPDATE_FP_NEXTNUMBER",
  syarat: "Setiap AR Invoice, AR DP Invoice, atau AP Credit Memo baru disimpan.", kondisi: "Object 13 / 203 / 19, transaksi Add",
  does: "Memanggil procedure <code>STEM_UPDATE_FP_NEXTNUMBER</code> untuk memajukan nomor Faktur Pajak berikutnya." };
const planCube = (no, tbl, ln = "U_STEM_PlanDocEntry") => ({ k: "proc", no, name: "Tandai Plan berubah", when: AU, anchor: `INTO planEntry FROM ${tbl}`,
  syarat: "Dokumen terhubung ke sebuah Plan.", kondisi: `<code>${tbl}.${ln} ≠ 0</code>`, does: CUBE });

